    def __init__(self, client: "AsyncClient") -> None:
        self._client = client

    async def cancel(self, run_id: Union[str, int], *, request_options: Optional[RequestOptions] = None) -> "Run":
        """Cancel a run

        Cancels a long run that is still running. The run's code stops, the run ends `cancelled`, and Reminix sends a `run.cancelled` event. The person who started the run, the script owner, a workspace owner or admin, or a workspace API key can cancel it."""
        return await self._client._call(
            {"method": "post", "path": "/runs/{runId}/cancel", "query": [], "body": False, "names": {}},
            {"runId": run_id},
            {},
            request_options,
        )

    async def create(self, slug: Union[str, int], *, inputs: Dict[str, Any] = NOT_GIVEN, via: Literal["api", "cli"] = NOT_GIVEN, request_options: Optional[RequestOptions] = None) -> Union["Run", "RunAwaitingApproval"]:
        """Run a script

        Runs the script's published version with these inputs, and returns the run when it finishes, with its output or error. Reminix first checks the inputs against the version's input schema. If they don't match, the request returns 400 with one `details` entry per field. For a file input, pass a file id or an https link that Reminix fetches. The id can be a file you uploaded with files.upload, or a file another run saved. The script runs on its own fresh machine and can reach only the hosts its version declares. A run can last up to its version's `timeoutSeconds`, at most 30, counted from when its code starts. Getting a machine can take up to 2 minutes first. If the run is still in progress after 60 seconds, the request returns 202 with status `running`, and you follow the run with runs.get. If the version's `timeoutSeconds` is over 30, the run is a long run. A long run runs durably, and the request returns 202 at once. Every run counts toward the workspace's `runs` usage."""
